// Parse delivery data
const data = $input.first().json;

return [{
  json: {
    customer_name: data.customer_name || 'Customer',
    customer_phone: data.customer_phone || '',
    product_name: data.product_name || 'Your order',
    delivery_date: data.delivery_date || new Date().toISOString().split('T')[0]
  }
}];

// Wait 7 days before sending feedback request
// This node simulates the wait
const data = $input.first().json;
const sevenDaysLater = new Date();
sevenDaysLater.setDate(sevenDaysLater.getDate() + 7);

return [{
  json: {
    ...data,
    feedback_due_date: sevenDaysLater.toISOString().split('T')[0],
    message: `Hi ${data.customer_name}!\n\nSudah seminggu produk ${data.product_name} sampai ya.\n\nBagaimana hasilnya? Silakan share feedback Anda:\n- WhatsApp: +62 811-2127-464\n- Email: cs@duanaga.co.id\n\nMasukan Anda sangat berarti untuk kami!`
  }
}];

// Log feedback request sent
const data = $input.first().json;
console.log('Feedback request sent to:', data.customer_name);
return [{ json: { status: 'success', sent_to: data.customer_name } }];
